def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        if history[0][1] == 'D' and history[1][1] == 'D':
            return 'D'
        return 'C'

    last_me, last_opp = history[-1]
    prev_me, prev_opp = history[-2]

    opp_defects = sum(1 for _, o in history if o == 'D')
    my_defects = sum(1 for m, _ in history if m == 'D')
    opp_coops = n - opp_defects

    # Detect relentless defector quickly.
    if opp_defects == n:
        return 'D'

    # If opponent has been perfectly cooperative, maintain mutual cooperation.
    if opp_defects == 0:
        if n >= 97:
            return 'D'
        return 'C'

    opp_rate = opp_coops / n

    # Recent window of opponent behavior.
    window = history[-12:] if n >= 12 else history
    recent_opp_d = sum(1 for _, o in window if o == 'D')
    recent_opp_c = len(window) - recent_opp_d

    # If opponent is defecting almost all the time, defect.
    if recent_opp_d >= len(window) - 1 and opp_rate < 0.35:
        return 'D'

    # Occasional late exploitation against heavy cooperators.
    if n >= 85 and opp_rate > 0.85 and my_defects < 3:
        if n % 7 == 0:
            return 'D'
        return 'C'

    # Opponent just defected.
    if last_opp == 'D':
        # Forgive a rare isolated defection from an otherwise cooperative partner.
        if opp_rate >= 0.75 and opp_defects <= 2 and recent_opp_d == 1:
            if last_me == 'D':
                return 'C'
            return 'C' if rng.random() < 0.8 else 'D'
        # If we both just defected, try a conciliatory probe to break the cycle.
        if last_me == 'D' and prev_opp == 'D':
            if recent_opp_d <= 3 and rng.random() < 0.35:
                return 'C'
            return 'D'
        # If our previous response was a single punishment, return to cooperation.
        if last_me == 'C' and prev_opp == 'C':
            return 'D'
        # Continued retaliation.
        if recent_opp_d >= 4:
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    if last_me == 'D':
        # We punished; restore cooperation if opponent responded with C.
        if opp_rate >= 0.3:
            return 'C'
        if recent_opp_d >= 4:
            return 'D'
        return 'C'

    # Both cooperated last round. Preserve cooperation.
    if recent_opp_d == 0:
        return 'C'

    # Mostly cooperative partner with some defections: keep cooperating.
    if opp_rate >= 0.6:
        if n >= 95 and opp_rate > 0.8:
            return 'D'
        return 'C'

    # Mixed partner: mildly reciprocate recent defections but lean cooperative.
    if recent_opp_d >= 3:
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    return 'C'
